package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	fmt.Fscan(in, &n, &m)

	width, height := n, m
	if width > height {
		width, height = height, width
	}

	maskCount := 1 << width
	fullMask := maskCount - 1

	popcount := make([]int, maskCount)
	horizontal := make([]int, maskCount)
	for mask := 0; mask < maskCount; mask++ {
		popcount[mask] = popcount[mask>>1] + mask&1
		horizontal[mask] = (mask | (mask << 1) | (mask >> 1)) & fullMask
	}

	const inf = int(1e9)
	stateCount := maskCount * maskCount
	dp := make([]int, stateCount)
	next := make([]int, stateCount)

	for i := range dp {
		dp[i] = inf
	}
	for mask := 0; mask < maskCount; mask++ {
		dp[mask] = popcount[mask]
	}

	for row := 0; row < height-1; row++ {
		for i := range next {
			next[i] = inf
		}

		for upper := 0; upper < maskCount; upper++ {
			for current := 0; current < maskCount; current++ {
				cost := dp[upper*maskCount+current]
				if cost == inf {
					continue
				}

				for lower := 0; lower < maskCount; lower++ {
					if horizontal[current]|upper|lower != fullMask {
						continue
					}

					index := current*maskCount + lower
					newCost := cost + popcount[lower]
					if newCost < next[index] {
						next[index] = newCost
					}
				}
			}
		}
		dp, next = next, dp
	}

	minSpiders := inf
	for upper := 0; upper < maskCount; upper++ {
		for current := 0; current < maskCount; current++ {
			if horizontal[current]|upper != fullMask {
				continue
			}
			cost := dp[upper*maskCount+current]
			if cost < minSpiders {
				minSpiders = = cost
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, n*m-minSpiders)
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	fmt.Fscan(in, &n, &m)

	width, rows := n, m
	if width > rows {
		width, rows = rows, width
	}

	size := 1 << width
	all := size - 1
	const inf = int(1e9)

	horizontal := make([]int, size)
	count := make([]int, size)
	for mask := 0; mask < size; mask++ {
		horizontal[mask] = (mask | (mask << 1) | (mask >> 1)) & all
		count[mask] = bits.OnesCount(uint(mask))
	}

	dp := make([][]int, size)
	next := make([][]int, size)
	for i := 0; i < size; i++ {
		dp[i] = make([]int, size)
		next[i] = make([]int, size)
		for j := 0; j < size; j++ {
			dp[i][j] = inf
			next[i][j] = inf
		}
	}

	for mask := 0; mask < size; mask++ {
		dp[0][mask] = count[mask]
	}

	for row := 0; row < rows-1; row++ {
		for i := 0; i < size; i++ {
			for j := 0; j < size; j++ {
				next[i][j] = inf
			}
		}

		for above := 0; above < size; above++ {
			for current := 0; current < size; current++ {
				if dp[above][current] == inf {
					continue
				}
				covered := above | horizontal[current]
				for below := 0; below < size; below++ {
					if covered|below != all {
						continue
					}
					value := dp[above][current] + count[below]
					if value < next[current][below] {
						next[current][below] = value
					}
				}
			}
		}

		dp, next = next, dp
	}

	minOccupied := inf
	for above := 0; above < size; above++ {
		for current := 0; current < size; current++ {
			if dp[above][current] < minOccupied &&
				(above|horizontal[current]) == all {
				minOccupied = dp[above][current]
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, n*m-minOccupied)
}

