import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	fmt.Fscan(in, &n, &m)

	w, h := n, m
	if w > h {
		w, h = h, w
	}

	size := 1 << w
	full := size - 1
	const inf = int(1e9)

	horizontal := make([]int, size)
	count := make([]int, size)
	for mask := 0; mask < size; mask++ {
		horizontal[mask] = mask | ((mask << 1) & full) | (mask >> 1)
		count[mask] = bits.OnesCount(uint(mask))
	}

	dp := make([]int, size*size)
	next := make([]int, size*size)
	for i := range dp {
		dp[i] = inf
	}
	for mask := 0; mask < size; mask++ {
		dp[mask] = count[mask]
	}

	for row := 1; row < h; row++ {
		for i := range next {
			next[i] = inf
		}

		for prevPrev := 0; prevPrev < size; prevPrev++ {
			for prev := 0; prev < size; prev++ {
				value := dp[prevPrev*size+prev]
				if value == inf {
					continue
				}

				missing := full &^ (horizontal[prev] | prevPrev)
				for cur := missing; ; cur = (cur - 1) & full {
					if cur&missing == missing {
						idx := prev*size + cur
						candidate := value + count[cur]
						if candidate < next[idx] {
							next[idx] = candidate
						}
					}
					if cur == 0 {
						break
					}
				}
			}
		}
		dp, next = next, dp
	}

	minOccupied := inf
	for prevPrev := 0; prevPrev < size; prevPrev++ {
		for prev := 0; prev < size; prev++ {
			value := dp[prevPrev*size+prev]
			if value < minOccupied && horizontal[prev]|prevPrev == full {
				minOccupied = value
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, n*m-minOccupied)
}

